import csv
import io


def parse_csv(raw_csv: str):
    width = 3
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    def fit_width(row):
        if len(row) > width:
            return row[:width - 1] + [",".join(row[width - 1:])]
        return row + [""] * (width - len(row))

    prefix = []
    for row in reader:
        if len(row) == width and any(field.strip() for field in row):
            return {
                "columns": row,
                "rows": [fit_width(record) for record in reader],
            }
        if prefix or any(field.strip() for field in row):
            prefix.append(row)

    if not prefix:
        return {"columns": [], "rows": []}

    return {
        "columns": fit_width(prefix[0]),
        "rows": [fit_width(record) for record in prefix[1:]],
    }
